@startuml

class Doctor {
  + practitionerNumber : int
  + signature : string
  + fullName : string
  + address : string
  + phoneNumber : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
}

class Test {
  + duration : int
}

class TestGroup {
  + name : string
}

class RepetitionPattern {
  + interval : string
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class Lab {
  + address : string
  + registrationNumber : string
  + fee : float
}

class BusinessHours {
  + startTime : time
  + endTime : time
}

class TestResult {
  + isPositive : boolean
  + report : string
}

class AppointmentType {
  + type : string
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Requisition "0..1" -- "0..1" RepetitionPattern : follows
RepetitionPattern "1" -- "1" Interval : has

Test "1" -- "0..*" TestResult : produces
Test "1" -- "0..*" Appointment : scheduled for
Patient "1" -- "*" Appointment : books
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" BusinessHours : operates during

@enduml

